<?php
session_start();require_once __DIR__.'/config/database.php';if(!isset($_SESSION['cart']))$_SESSION['cart']=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['action']??'';$id=(int)($_POST['product_id']??0);if($a==='empty')$_SESSION['cart']=[];elseif($a==='remove')unset($_SESSION['cart'][$id]);elseif($a==='update'&&$id){$q=max(1,(int)$_POST['quantity']);$s=$conn->prepare("SELECT stock FROM products WHERE id=?");$s->bind_param("i",$id);$s->execute();$p=$s->get_result()->fetch_assoc();if($p&&$p['stock']>0)$_SESSION['cart'][$id]=min($q,(int)$p['stock']);else unset($_SESSION['cart'][$id]);}header('Location:cart.php');exit;}
$items=[];$subtotal=0;$count=0;$ids=array_keys($_SESSION['cart']);if($ids){$ids=array_map('intval',$ids);$ph=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$s=$conn->prepare("SELECT id,name,price,stock,image FROM products WHERE id IN ($ph)");$s->bind_param($types,...$ids);$s->execute();$r=$s->get_result();while($p=$r->fetch_assoc()){$q=min((int)($_SESSION['cart'][$p['id']]??0),(int)$p['stock']);if($q<1)continue;$p['q']=$q;$p['total']=$q*(float)$p['price'];$items[]=$p;$subtotal+=$p['total'];$count+=$q;}}$delivery=$subtotal>0&&$subtotal<300?4.99:0;$grand=$subtotal+$delivery;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cart</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body><nav class="navbar main-navbar"><div class="container"><a class="navbar-brand text-white fw-bold" href="index.php">SmartStore</a><a href="categories.php" class="text-white text-decoration-none">Continue Shopping</a></div></nav><main class="container py-5"><h1 class="fw-bold text-dark-custom mb-4">Your Cart</h1><div class="row g-4"><div class="col-lg-8"><?php if(!$items):?><div class="empty-state"><h4>Your cart is empty</h4><a href="categories.php" class="btn custom-primary rounded-pill mt-2">Shop Products</a></div><?php else:foreach($items as $i):?><div class="cart-product-card"><div class="cart-product-image"><?php if($i['image']):?><img src="admin/assets/images/products/<?=htmlspecialchars($i['image'])?>" alt="<?=htmlspecialchars($i['name'])?>"><?php else:?><i class="bi bi-image fs-2"></i><?php endif;?></div><div class="flex-grow-1"><h5 class="fw-bold"><?=htmlspecialchars($i['name'])?></h5><span class="text-custom-primary fw-bold">$<?=number_format($i['price'],2)?></span></div><form method="post" class="d-flex gap-2"><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?=$i['id']?>"><input class="form-control cart-qty" type="number" name="quantity" min="1" max="<?=$i['stock']?>" value="<?=$i['q']?>"><button class="btn btn-outline-secondary">✓</button></form><strong>$<?=number_format($i['total'],2)?></strong><form method="post"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$i['id']?>"><button class="btn btn-link text-danger">×</button></form></div><?php endforeach;?><form method="post"><input type="hidden" name="action" value="empty"><button class="btn btn-outline-danger rounded-pill">Empty Cart</button></form><?php endif;?></div><div class="col-lg-4"><div class="summary-card"><h4 class="fw-bold">Order Summary</h4><div class="d-flex justify-content-between mt-4"><span>Items</span><strong><?=$count?></strong></div><div class="d-flex justify-content-between"><span>Subtotal</span><strong>$<?=number_format($subtotal,2)?></strong></div><div class="d-flex justify-content-between"><span>Delivery</span><strong><?=$delivery?'$'.number_format($delivery,2):'FREE'?></strong></div><hr><div class="d-flex justify-content-between"><strong>Grand Total</strong><strong class="summary-total">$<?=number_format($grand,2)?></strong></div><?php if($items):?><a href="checkout.php" class="btn custom-primary w-100 rounded-pill mt-4">Proceed to Checkout</a><?php endif;?></div></div></div></main></body></html>